fun main() {
    var firstLine = true
    System.stdin.buffer.reader().forEachLine { line ->
        if (firstLine) {
            firstLine = false
            return@forEachLine
        }
        val arr = line.split(" ").map { it.toInt() }.sorted()
        var ans = 0
        var prev = -1
        for (num in arr) {
            if (prev != num && num != 0) {
                ans++
                prev = num
            }
        }
        println(ans)
    }
}

